import csv
import sys
import statistics


def summarize_numeric_columns(filepath):
    with open(filepath, newline="", encoding="utf-8") as f:
        reader = csv.DictReader(f)
        headers = reader.fieldnames
        if not headers:
            print("No headers found.")
            return

        columns = {h: [] for h in headers}
        for row in reader:
            for h in headers:
                val = row.get(h, "")
                try:
                    columns[h].append(float(val))
                except ValueError:
                    pass

    numeric_cols = {h: v for h, v in columns.items() if v}
    if not numeric_cols:
        print("No numeric columns found.")
        return

    for name, values in numeric_cols.items():
        print(f"--- {name} ---")
        print(f"  count:  {len(values)}")
        print(f"  mean:   {statistics.mean(values):.4f}")
        print(f"  std:    {statistics.stdev(values):.4f}" if len(values) > 1 else "  std:    N/A")
        print(f"  min:    {min(values):.4f}")
        print(f"  25%:    {statistics.quantiles(values, n=4)[0]:.4f}" if len(values) >= 4 else "  25%:    N/A")
        print(f"  50%:    {statistics.median(values):.4f}")
        print(f"  75%:    {statistics.quantiles(values, n=4)[2]:.4f}" if len(values) >= 4 else "  75%:    N/A")
        print(f"  max:    {max(values):.4f}")
        print()


if __name__ == "__main__":
    if len(sys.argv) != 2:
        print(f"Usage: {sys.argv[0]} <csv_file>")
        sys.exit(1)
    summarize_numeric_columns(sys.argv[1])
